package com.nigson.commerce.fulfillment;
import java.util.*;
import java.time.*;
import java.math.*;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.commerce.pricing.CarrierPacking;
import com.nigson.commerce.pricing.PricingValues;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Order-first local statements. Stock movement is the application service's atomic local port. */
public final class JdbcShipmentRepository implements ShipmentRepository {
 private final JdbcTemplate jdbc;private final Clock clock;private final FulfillmentPolicy policy;
 public JdbcShipmentRepository(JdbcTemplate jdbc,Clock clock,FulfillmentPolicy policy){this.jdbc=jdbc;this.clock=clock;this.policy=policy;}
 public Map<String,Object> order(UUID id,boolean lock){var rows=jdbc.queryForList("SELECT * FROM commerce.sales_order WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 public UUID orderId(UUID shipment){var ids=jdbc.query("SELECT order_id FROM commerce.shipment WHERE id=?",(r,n)->r.getObject(1,UUID.class),shipment);if(ids.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return ids.getFirst();}
 public FulfillmentValues.Shipment find(UUID id,boolean lock){var rows=jdbc.query("SELECT id,order_id,status,tracking_url,version FROM commerce.shipment WHERE id=?"+(lock?" FOR UPDATE":""),(r,n)->new FulfillmentValues.Shipment(id,r.getObject("order_id",UUID.class),r.getString("status"),List.of(),r.getString("tracking_url"),r.getLong("version")),id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var s=rows.getFirst();var lines=jdbc.query("SELECT order_line_id,sum(quantity) quantity FROM commerce.shipment_line WHERE shipment_id=? GROUP BY order_line_id ORDER BY order_line_id LIMIT 101",(r,n)->new FulfillmentValues.ShipmentLine(r.getObject("order_line_id",UUID.class),PricingValues.decimal(r.getBigDecimal("quantity"))),id);if(lines.isEmpty()||lines.size()>100)throw FulfillmentValues.rule();return new FulfillmentValues.Shipment(s.id(),s.orderId(),s.status(),List.copyOf(lines),s.trackingUrl(),s.version());}
 private void paid(Map<String,Object> o){if(!Set.of("PAID","PROCESSING","SHIPPED").contains(o.get("status"))||!Set.of("PAID","PARTIALLY_REFUNDED").contains(o.get("payment_status"))||o.get("hold_reason")!=null||!"NGN".equals(o.get("currency_code")))throw FulfillmentValues.rule();var carrier=EventCodec.JSON.readTree(o.get("carrier_snapshot").toString());String carrierMode=string(carrier,"mode");String paymentMode=carrierMode.equals("SANDBOX")?"TEST":carrierMode;if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.payment_attempt a JOIN commerce.payment_transaction t ON t.attempt_id=a.id WHERE a.order_id=? AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL AND a.expected_amount=? AND t.settled_amount=a.expected_amount AND a.currency_code='NGN' AND t.currency_code='NGN' AND a.provider_mode=t.provider_mode AND a.provider_mode=? AND a.provider='PAYSTACK' AND t.provider_status='success')",Boolean.class,o.get("id"),o.get("grand_total"),paymentMode)))throw FulfillmentValues.rule();}
 private String string(tools.jackson.databind.JsonNode n,String name){var value=n.get(name);if(value==null||!value.isString()||value.asString().isBlank())throw FulfillmentValues.rule();return value.asString();}
 private String nullable(tools.jackson.databind.JsonNode n,String name){var value=n.get(name);return value==null||value.isNull()?null:string(n,name);}
 private CarrierPacking.Address address(Map<String,Object> o){var n=EventCodec.JSON.readTree(o.get("address_snapshot").toString());try{return new CarrierPacking.Address(string(n,"recipient"),string(n,"phone"),string(n,"line1"),nullable(n,"line2"),string(n,"city"),string(n,"region"),nullable(n,"postalCode"),string(n,"countryCode"));}catch(Problem.Failure bad){throw FulfillmentValues.rule();}}
 private BigDecimal cancelled(UUID order,UUID line){return jdbc.queryForObject("SELECT coalesce(-sum(delta_allocated),0) FROM commerce.inventory_movement WHERE order_id=? AND order_line_id=? AND movement_type='RETURN' AND return_kind='UNSHIPPED_CANCEL'",BigDecimal.class,order,line);}
 private BigDecimal refunded(UUID order,UUID line){return jdbc.queryForObject("SELECT coalesce(sum(l.quantity),0) FROM commerce.refund_line l JOIN commerce.refund r ON r.id=l.refund_id WHERE r.order_id=? AND l.order_line_id=? AND r.state='SUCCEEDED'",BigDecimal.class,order,line);}
 private BigDecimal claimed(UUID line,UUID excluded){return jdbc.queryForObject("SELECT coalesce(sum(l.quantity),0) FROM commerce.shipment_line l JOIN commerce.shipment s ON s.id=l.shipment_id WHERE l.order_line_id=? AND s.status<>'CANCELLED' AND (?::uuid IS NULL OR s.id<>?::uuid)",BigDecimal.class,line,excluded,excluded);}
 private List<CarrierPacking.Parcel> packages(UUID order,List<FulfillmentValues.LineInput> lines){var quantities=new TreeMap<UUID,BigDecimal>(Comparator.comparing(UUID::toString));var packaging=new HashMap<UUID,CarrierPacking.Item>();var proposed=new HashMap<UUID,BigDecimal>();for(var line:lines)proposed.merge(line.orderLineId(),new BigDecimal(line.quantity()),BigDecimal::add);var balanceRequests=new HashMap<UUID,BigDecimal>();for(var line:lines)balanceRequests.merge(line.balanceId(),new BigDecimal(line.quantity()),BigDecimal::add);for(var entry:balanceRequests.entrySet()){var allocated=jdbc.query("SELECT quantity FROM commerce.inventory_reservation WHERE order_id=? AND balance_id=? AND status='ALLOCATED'",(r,n)->r.getBigDecimal(1),order,entry.getKey());if(allocated.size()!=1)throw FulfillmentValues.rule();BigDecimal consumed=jdbc.queryForObject("SELECT coalesce(-sum(delta_allocated),0) FROM commerce.inventory_movement WHERE order_id=? AND balance_id=? AND movement_type IN ('DISPATCH','RETURN')",BigDecimal.class,order,entry.getKey());BigDecimal pending=jdbc.queryForObject("SELECT coalesce(sum(l.quantity),0) FROM commerce.shipment_line l JOIN commerce.shipment s ON s.id=l.shipment_id WHERE s.order_id=? AND l.balance_id=? AND s.status IN ('CREATED','READY','EXCEPTION')",BigDecimal.class,order,entry.getKey());if(entry.getValue().compareTo(allocated.getFirst().subtract(consumed).subtract(pending))>0)throw FulfillmentValues.rule();}for(var line:lines){var rows=jdbc.queryForList("SELECT ol.sku_id,ol.quantity,s.quantity_scale,s.carrier_packaging::text,b.sku_id balance_sku FROM commerce.order_line ol JOIN commerce.sku s ON s.id=ol.sku_id JOIN commerce.inventory_balance b ON b.id=? WHERE ol.id=? AND ol.order_id=?",line.balanceId(),line.orderLineId(),order);if(rows.size()!=1||!rows.getFirst().get("sku_id").equals(rows.getFirst().get("balance_sku")))throw new Problem.Failure(ProblemCode.NOT_FOUND);var r=rows.getFirst();UUID sku=(UUID)r.get("sku_id");BigDecimal quantity;try{quantity=PricingValues.quantity(line.quantity(),((Number)r.get("quantity_scale")).intValue());}catch(Problem.Failure invalid){throw FulfillmentValues.rule();}BigDecimal remaining=((BigDecimal)r.get("quantity")).subtract(cancelled(order,line.orderLineId()).max(refunded(order,line.orderLineId()))).subtract(claimed(line.orderLineId(),null));if(proposed.get(line.orderLineId()).compareTo(remaining)>0)throw FulfillmentValues.rule();if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.inventory_reservation WHERE order_id=? AND balance_id=? AND status='ALLOCATED')",Boolean.class,order,line.balanceId())))throw FulfillmentValues.rule();quantities.merge(sku,quantity,BigDecimal::add);packaging.put(sku,new CarrierPacking.Item(sku,quantity,((Number)r.get("quantity_scale")).intValue(),EventCodec.JSON.readTree(r.get("carrier_packaging").toString())));}var items=new ArrayList<CarrierPacking.Item>();for(var e:quantities.entrySet()){var original=packaging.get(e.getKey());items.add(new CarrierPacking.Item(e.getKey(),e.getValue(),original.scale(),original.packaging()));}try{return CarrierPacking.pack(items);}catch(Problem.Failure invalid){throw FulfillmentValues.rule();}}
 public FulfillmentValues.Shipment create(UUID id,FulfillmentValues.ShipmentInput input,String actor){var order=order(id,true);paid(order);var frozen=EventCodec.JSON.readTree(order.get("carrier_snapshot").toString());String mode=string(frozen,"mode"),service=string(frozen,"serviceCode");if(!string(frozen,"provider").equals("FEDEX")||!string(frozen,"currency").equals("NGN"))throw FulfillmentValues.rule();String approval=policy.require(mode,input.provider());policy.tracking(input.trackingUrl());var address=address(order);var parcels=packages(id,input.lines());UUID shipment=EventCodec.uuid7(clock.instant()),booking=EventCodec.uuid7(clock.instant());var snapshot=new LinkedHashMap<String,Object>();snapshot.put("schemaVersion",1);snapshot.put("mode",mode);snapshot.put("serviceCode",service);snapshot.put("address",address);snapshot.put("packages",parcels);snapshot.put("packageHash",CarrierPacking.hash(parcels));snapshot.put("bookingReference",booking.toString());snapshot.put("approvalReference",approval);String encoded=EventCodec.JSON.writeValueAsString(snapshot);if(EventCodec.JSON.writeValueAsBytes(snapshot).length>65536)throw FulfillmentValues.rule();jdbc.update("INSERT INTO commerce.shipment(id,created_by,updated_by,order_id,provider,provider_reference,tracking_url,status,booking_request_id,package_snapshot) VALUES (?,?,?,?,?,?,?,'CREATED',?,?::jsonb)",shipment,actor,actor,id,input.provider(),input.providerReference(),input.trackingUrl(),booking,encoded);for(var line:input.lines())jdbc.update("INSERT INTO commerce.shipment_line(id,created_by,updated_by,shipment_id,order_line_id,balance_id,quantity) VALUES (?,?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),actor,actor,shipment,line.orderLineId(),line.balanceId(),new BigDecimal(line.quantity()));if(input.provider().equals("MANUAL")&&input.providerReference()!=null){jdbc.update("INSERT INTO commerce.shipment_event(id,created_by,shipment_id,source,event_key,status,occurred_at) VALUES (?,?,?,'MANUAL',?,'BOOKED',?)",EventCodec.uuid7(clock.instant()),actor,shipment,booking.toString(),java.sql.Timestamp.from(clock.instant()));jdbc.update("UPDATE commerce.shipment SET status='READY' WHERE id=?",shipment);}return find(shipment,false);}
 public CarrierShipmentContext context(UUID id){
  var order=order(orderId(id),false);var shipment=find(id,false);if(!Set.of("CREATED","EXCEPTION").contains(shipment.status()))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);paid(order);
  var row=jdbc.queryForMap("SELECT provider,booking_request_id,package_snapshot::text FROM commerce.shipment WHERE id=?",id);if(!"FEDEX".equals(row.get("provider"))||row.get("booking_request_id")==null)throw FulfillmentValues.rule();
  var snapshot=EventCodec.JSON.readTree(row.get("package_snapshot").toString());var frozen=EventCodec.JSON.readTree(order.get("carrier_snapshot").toString());String mode=string(snapshot,"mode"),service=string(snapshot,"serviceCode"),reference=string(snapshot,"bookingReference");policy.require(mode,"FEDEX");
  if(!mode.equals(string(frozen,"mode"))||!service.equals(string(frozen,"serviceCode"))||!reference.equals(row.get("booking_request_id").toString()))throw FulfillmentValues.rule();
  try{
   var shipper=DeliveryQuoteValues.origin(frozen.path("providerSnapshot").path("shipper"));var recipient=address(order);if(!EventCodec.JSON.valueToTree(recipient).equals(snapshot.path("address")))throw FulfillmentValues.rule();
   var addressNode=EventCodec.JSON.readTree(order.get("address_snapshot").toString());if(!addressNode.propertyNames().equals(Set.of("label","recipient","phone","line1","line2","city","region","postalCode","countryCode","isDefault"))||!addressNode.path("isDefault").isBoolean())throw FulfillmentValues.rule();
   var immutable=EventCodec.JSON.treeToValue(addressNode,com.nigson.commerce.order.OrderValues.Address.class);com.nigson.commerce.party.PartyValues.text(immutable.label(),80,false);
   var rows=snapshot.path("packages");if(!rows.isArray()||rows.isEmpty()||rows.size()>100||!CarrierPacking.hash(rows).equals(string(snapshot,"packageHash")))throw FulfillmentValues.rule();var parcels=new ArrayList<CarrierPacking.Parcel>();
   for(var item:rows){if(!item.propertyNames().equals(Set.of("skuId","quantity","weightKg","lengthCm","widthCm","heightCm")))throw FulfillmentValues.rule();var parcel=EventCodec.JSON.treeToValue(item,CarrierPacking.Parcel.class);ApiValues.uuid(parcel.skuId()==null?null:parcel.skuId().toString());ApiValues.quantity(parcel.quantity());ApiValues.quantity(parcel.weightKg());for(String dimension:List.of(parcel.lengthCm(),parcel.widthCm(),parcel.heightCm()))if(ApiValues.money(dimension,true).signum()<=0)throw FulfillmentValues.rule();parcels.add(parcel);}
   return new CarrierShipmentContext(id,shipment.orderId(),immutable,shipper,service,List.copyOf(parcels),reference,mode);
  }catch(Problem.Failure invalid){throw FulfillmentValues.rule();}catch(IllegalArgumentException|NullPointerException invalid){throw FulfillmentValues.rule();}
 }
 private void version(FulfillmentValues.Shipment s,long expected){if(s.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();}
 public List<com.nigson.commerce.inventory.StockLedger.Line> stockLines(UUID shipment){var lines=jdbc.query("SELECT order_line_id,balance_id,quantity FROM commerce.shipment_line WHERE shipment_id=? ORDER BY balance_id,order_line_id LIMIT 101",(r,n)->new com.nigson.commerce.inventory.StockLedger.Line(r.getObject(1,UUID.class),r.getObject(2,UUID.class),PricingValues.decimal(r.getBigDecimal(3))),shipment);if(lines.isEmpty()||lines.size()>100)throw FulfillmentValues.rule();return lines;}
 public FulfillmentValues.Shipment dispatch(UUID id,long expected,String actor){var o=order(orderId(id),true);paid(o);var s=find(id,true);version(s,expected);if(!s.status().equals("READY"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);var proof=jdbc.queryForMap("SELECT provider,provider_reference,label_asset_id,package_snapshot::text FROM commerce.shipment WHERE id=?",id);var snapshot=EventCodec.JSON.readTree(proof.get("package_snapshot").toString());policy.require(string(snapshot,"mode"),proof.get("provider").toString());if(proof.get("provider_reference")==null||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.shipment_event WHERE shipment_id=? AND source=? AND status='BOOKED')",Boolean.class,id,proof.get("provider").toString())))throw FulfillmentValues.rule();if(proof.get("provider").equals("FEDEX")&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.asset_reference WHERE id=? AND shipment_id=? AND purpose='SHIPPING_LABEL' AND classification='PRIVATE' AND status='CLEAN' AND byte_size>0)",Boolean.class,proof.get("label_asset_id"),id)))throw FulfillmentValues.rule();for(var line:stockLines(id)){BigDecimal original=jdbc.queryForObject("SELECT quantity FROM commerce.order_line WHERE id=? AND order_id=?",BigDecimal.class,line.orderLineId(),s.orderId());if(claimed(line.orderLineId(),null).compareTo(original.subtract(cancelled(s.orderId(),line.orderLineId()).max(refunded(s.orderId(),line.orderLineId()))))>0)throw FulfillmentValues.rule();}jdbc.update("UPDATE commerce.shipment SET status='SHIPPED',dispatched_at=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(clock.instant()),java.sql.Timestamp.from(clock.instant()),actor,id);return find(id,false);}
 public FulfillmentValues.Shipment delivered(UUID id,long expected,FulfillmentValues.Delivery input,String actor){order(orderId(id),true);var s=find(id,true);version(s,expected);if(!s.status().equals("SHIPPED"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);var dispatched=jdbc.queryForObject("SELECT dispatched_at FROM commerce.shipment WHERE id=?",java.sql.Timestamp.class,id);if(dispatched==null||input.deliveredAt().isBefore(dispatched.toInstant())||input.deliveredAt().isAfter(clock.instant()))throw FulfillmentValues.rule();jdbc.update("UPDATE commerce.shipment SET status='DELIVERED',delivered_at=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(input.deliveredAt()),java.sql.Timestamp.from(clock.instant()),actor,id);return find(id,false);}
 public UUID organization(UUID order){return (UUID)order(order,false).get("organization_id");}
 public void lockOrder(UUID order){order(order,true);}
 public void event(UUID shipment,UUID command,String status,Instant occurred,String actor){jdbc.update("INSERT INTO commerce.shipment_event(id,created_by,shipment_id,source,event_key,status,occurred_at) VALUES (?,?,?,'OPERATIONS',?,?,?)",EventCodec.uuid7(clock.instant()),actor,shipment,command.toString(),status,java.sql.Timestamp.from(occurred));}
 public void progress(UUID id,String actor){var o=order(id,true);if(!Set.of("PAID","PROCESSING","SHIPPED","DELIVERED").contains(o.get("status")))return;var quantities=jdbc.queryForList("SELECT id,quantity FROM commerce.order_line WHERE order_id=? ORDER BY id LIMIT 101",id);if(quantities.isEmpty()||quantities.size()>100)throw FulfillmentValues.rule();boolean allShipped=true,allDelivered=true,anyShipped=false;for(var line:quantities){UUID lineId=(UUID)line.get("id");BigDecimal required=((BigDecimal)line.get("quantity")).subtract(cancelled(id,lineId));BigDecimal shipped=jdbc.queryForObject("SELECT coalesce(sum(l.quantity),0) FROM commerce.shipment_line l JOIN commerce.shipment s ON s.id=l.shipment_id WHERE l.order_line_id=? AND s.status IN ('SHIPPED','DELIVERED')",BigDecimal.class,lineId);BigDecimal delivered=jdbc.queryForObject("SELECT coalesce(sum(l.quantity),0) FROM commerce.shipment_line l JOIN commerce.shipment s ON s.id=l.shipment_id WHERE l.order_line_id=? AND s.status='DELIVERED'",BigDecimal.class,lineId);if(required.signum()<0||shipped.compareTo(required)>0||delivered.compareTo(shipped)>0)throw FulfillmentValues.rule();allShipped&=shipped.compareTo(required)==0;allDelivered&=delivered.compareTo(required)==0;anyShipped|=shipped.signum()>0;}String state=allDelivered&&anyShipped?"DELIVERED":allShipped&&anyShipped?"SHIPPED":anyShipped?"PROCESSING":o.get("status").toString();String fulfillment=allDelivered&&anyShipped?"DELIVERED":allShipped&&anyShipped?"SHIPPED":anyShipped?"PARTIALLY_SHIPPED":o.get("fulfillment_status").toString();if(!state.equals(o.get("status"))||!fulfillment.equals(o.get("fulfillment_status"))){if(((Number)o.get("version")).longValue()==Long.MAX_VALUE)throw FulfillmentValues.rule();jdbc.update("UPDATE commerce.sales_order SET status=?,fulfillment_status=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",state,fulfillment,java.sql.Timestamp.from(clock.instant()),actor,id);jdbc.update("INSERT INTO commerce.order_status_history(id,created_by,order_id,previous_status,new_status,reason) VALUES (?,?,?,?,?,?)",EventCodec.uuid7(clock.instant()),actor,id,o.get("status"),state,"Physical shipment progress");}}

}
